arguments.command:
python -c "
import pandas as pd
df = pd.read_csv('nlo_shg_eg_train.csv')
for i, row in df.iterrows():
    if 'N' in row['formula'] or 'O' in row['formula']:
        if 'Na' not in row['formula'] and 'Nb' not in row['formula']:
            # be careful about Na, Nb, Mo, Sn
            elements = row['formula'].split()
            if 'N' in elements or 'O' in elements:
                print(row['formula'], row['shg'], row['band_gap'])
"

